/** Number of strategies an operator applies to (0 if none). */
export function operatorStrategyCount(opId: number, map: StrategyOperatorMapping): number {
  return map.operatorToStrategies[opId]?.length ?? 0;
}

/** Operator ids applicable to a strategy (empty if none/unknown). */
export function strategyOperators(mevId: string, map: StrategyOperatorMapping): number[] {
  return map.strategyToOperators[mevId] ?? [];
}
